import { getSupabase } from '../_lib/supabase.js';
import { validateOrder, generateOrderNumber } from '../_lib/validators.js';
import { getCorsHeaders, handleOptions } from '../_shared/cors.js';

export async function onRequest(context) {
    const { request, env } = context;

    if (request.method === 'OPTIONS') {
        return handleOptions(request);
    }

    const corsHeaders = getCorsHeaders(request);

    if (request.method !== 'POST') {
        return new Response(
            JSON.stringify({ error: 'Method not allowed' }),
            { status: 405, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
    }

    try {
        const body = await request.json();
        const validation = validateOrder(body);

        if (!validation.valid) {
            return new Response(
                JSON.stringify({ error: 'Validation failed', details: validation.errors }),
                { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
            );
        }

        const supabase = getSupabase(env);
        const orderNumber = generateOrderNumber();
        const deliveryFee = validation.calculatedTotal >= 499 ? 0 : 40;
        const total = validation.calculatedTotal + deliveryFee;

        const items = body.items.map(item => ({
            id: item.id,
            name: item.name,
            price: item.price,
            quantity: item.quantity,
            image: item.image || '',
            lineTotal: item.price * item.quantity,
        }));

        const { data, error } = await supabase
            .from('orders')
            .insert({
                order_number: orderNumber,
                customer_name: body.customerName.trim(),
                customer_email: body.customerEmail || null,
                customer_phone: body.customerPhone.trim(),
                customer_address: body.customerAddress.trim(),
                customer_notes: body.customerNotes || null,
                payment_method: body.paymentMethod,
                payment_status: 'pending',
                subtotal: validation.calculatedTotal,
                delivery_fee: deliveryFee,
                discount: body.discount || 0,
                total: total,
                status: 'confirmed',
                items: items,
                estimated_delivery: new Date(Date.now() + 45 * 60 * 1000).toISOString(),
            })
            .select('id, order_number, status, estimated_delivery, created_at')
            .single();

        if (error) {
            console.error('Supabase error:', error);
            return new Response(
                JSON.stringify({ error: 'Failed to create order', details: error.message }),
                { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
            );
        }

        return new Response(
            JSON.stringify({
                success: true,
                order: {
                    id: data.id,
                    orderNumber: data.order_number,
                    status: data.status,
                    estimatedDelivery: data.estimated_delivery,
                    createdAt: data.created_at,
                },
            }),
            { status: 201, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );

    } catch (error) {
        console.error('Error:', error);
        return new Response(
            JSON.stringify({ error: 'Internal server error', details: error.message }),
            { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
    }
}